"""Build the static HTML from explicit, editable scientific content. No packages."""
from pathlib import Path
from html import escape
import re

ROOT=Path(__file__).parent
def eq(s): return '<div class="eq">\\['+escape(s)+'\\]</div>'
def p(s):
    # Preserve intentional markup, but inequalities such as 0<b<H are text.
    s=re.sub(r'<(?!/?[A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*|/?)>)','&lt;',s)
    return '<p>'+s+'</p>'
def h(s): return '<h3>'+s+'</h3>'
def table(head,rows):
    return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+c+'</th>' for c in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(s): return '<aside class="callout">'+p(s)+'</aside>'
def cite(n): return f' <a class="source-ref" href="#ref-{n}" data-source="true">[{n}]</a>'

symbols=table(['Symbol','Meaning / units'],[
    (r'\(H,R,A=\pi R^2\)','Internal height, radius, and cross-sectional area; m, m, m².'),
    (r'\(M,b\)','Empty-bottle mass and its CG height above the internal bottom; kg, m.'),
    (r'\(\rho,h,s\)','Uniform water density, water depth, and an integration height; kg/m³, m, m.'),
    (r'\(m,z,t\)','Remaining water mass, combined vertical CG, and time; kg, m, s.'),
    (r'\(k=\rho A\)','Water mass per unit height; kg/m.'),
    (r'\(u=h/H,\ f=m/m_{\rm full},\ \beta=b/H\)','Dimensionless depth, water mass fraction, and empty-bottle CG. For a cylinder, u=f.'),
    (r'\(r=M/m_{\rm full},\ y=z/H,\ \tau=t/T\)','Bottle/full-water mass ratio, dimensionless CG, and time fraction for a total drinking duration T.')])

def simulator(prefix,advanced=False):
    extra='''<label for="shape">Area slope <output id="shape-value">0.00</output></label><input id="shape" type="range" min="-0.85" max="0.85" step="0.05" value="0"><div class="ends"><span>Broad base</span><span>Broad top</span></div>''' if advanced else ''
    return f'''<div class="explorer" data-simulator="{prefix}"><div class="controls"><h3>Parameters</h3>
<label for="{prefix}-fill">Water remaining <output id="{prefix}-fill-value">50%</output></label><input id="{prefix}-fill" type="range" min="0" max="100" step="0.1" value="50"><div class="ends"><span>Empty</span><span>Full</span></div>
<label for="{prefix}-mass">Empty-bottle mass ÷ full water-load mass <output id="{prefix}-mass-value">0.125</output></label><input id="{prefix}-mass" aria-describedby="{prefix}-mass-help" type="range" min="-2.5" max="1" step="any" value="-0.90308998699"><div class="ends"><span>0.003</span><span>10</span></div>
<p class="tiny" id="{prefix}-mass-help">How heavy the empty bottle is compared with the water it holds when full. 0.125 means 100 g of bottle per 800 g of full-capacity water. At fixed water remaining, this changes the combined CG, not the water surface.</p>
<label for="{prefix}-base">Empty-bottle CG height ÷ internal height <output id="{prefix}-base-value">0.50</output></label><input id="{prefix}-base" aria-describedby="{prefix}-base-help" type="range" min="0" max="1" step="0.01" value="0.5"><div class="ends"><span>Bottom</span><span>Top</span></div>
<p class="tiny" id="{prefix}-base-help">Where the empty bottle balances, measured upward from the internal bottom: 0.25 is quarter-height, 0.50 midpoint, and 0.75 three-quarter-height. This redistributes bottle mass without changing the water volume or interior.</p>{extra}
<label for="{prefix}-speed">Playback speed</label><select id="{prefix}-speed" aria-describedby="{prefix}-speed-help"><option value="0.5">0.5× — full to empty in 40 seconds</option><option value="1">1× — full to empty in 20 seconds</option><option value="2" selected>2× — full to empty in 10 seconds</option><option value="4">4× — full to empty in 5 seconds</option><option value="8">8× — full to empty in 2.5 seconds</option></select>
<p class="tiny" id="{prefix}-speed-help">Default: 2×. Speed changes animation time only; the CG curve and minimum stay the same. Playback starts at the current fill, so a half-full bottle takes half the listed time. Near the minimum the CG naturally moves very little vertically because the curve is flat, even while water continues to leave.</p>
<div class="buttonrow"><button class="primary" id="{prefix}-play">Play</button><button id="{prefix}-reset">Reset</button><button id="{prefix}-csv">CSV</button></div>
<p class="tiny">{'Uniform density; fixed upright shape. Water remaining means volume fraction, not depth fraction.' if advanced else 'Upright rigid cylinder; settled water. Mass ratio uses a logarithmic slider.'}</p>
<svg class="diagram" id="{prefix}-bottle" viewBox="0 0 300 240" role="img" aria-label="Computed bottle cross-section with water surface and combined center of gravity"></svg>
<div class="status" id="{prefix}-status" aria-live="polite"></div></div>
<div class="plotbox"><h3>Center of gravity during emptying</h3><svg id="{prefix}-plot" class="plot" viewBox="0 0 800 420" role="img" aria-label="CG and water surface versus fraction consumed"></svg>
<div class="legend"><span><i style="background:var(--cyan)"></i>Combined CG</span><span><i style="background:#8ba3ba"></i>Water surface</span><span><i style="background:var(--gold)"></i>Empty-bottle CG / minimum</span></div>
<div class="metrics" aria-live="polite"><div>Current CG<strong id="{prefix}-current">0.300 H</strong></div><div>Minimum CG<strong class="gold" id="{prefix}-minimum">0.250 H</strong></div><div>Water at minimum<strong id="{prefix}-critical">25%</strong></div></div>
<p class="tiny">Horizontal axis: fraction consumed. It equals elapsed-time fraction only at constant water-mass removal rate. All curves are model predictions, not measurements.</p></div></div>'''+slider_guide(prefix, advanced)

def slider_guide(prefix, advanced):
    return '<section class="reading" id="'+prefix+'-slider-guide"><h3>What do the two ratios mean—and why does the surface stay fixed?</h3>'+p('The water surface is the boundary between water and air. The combined CG is the balance point of all remaining mass. These are different locations. With the bottle interior held fixed, changing the bottle’s mass or its balance point does not add or remove water, so it does not move that boundary.')+table(['Control','Meaning','What changes at fixed fill?'],[
        ('Water remaining','Remaining water volume divided by full internal capacity.','Water volume and surface height; the water’s own CG and the combined CG also change.'),
        ('Empty-bottle mass ÷ full water-load mass','Empty-bottle mass M divided by the water mass m_full at full capacity: r=M/m_full.','The weight assigned to the bottle in the combined balance. The full-capacity water mass is the reference even when almost empty.'),
        ('Empty-bottle CG height ÷ internal height','Empty-bottle CG height b above the internal bottom divided by internal height H: β=b/H.','The bottle’s own balance-point height, and hence the combined CG. Water volume and its own CG stay fixed.')])+p('For the mass slider, imagine making the bottle heavier while preserving its interior and its own CG height. A larger ratio pulls the combined CG closer to the empty bottle’s CG. A smaller ratio gives the remaining water more influence. The numerator is the empty bottle alone; it excludes the water. The denominator is the full water load alone; it excludes the bottle. This ratio is neither the fraction of water remaining nor the bottle’s fraction of the current total mass.')+p('For the height slider, imagine moving material from the bottle’s base toward its neck while keeping total bottle mass and interior geometry fixed. A value of 0.25 describes a low balance point, 0.50 a midpoint balance point, and 0.75 a high balance point. This is the CG of the empty bottle, not the CG of the water or the combined system. These controls idealize independently adjustable mass properties; rebuilding a real bottle could also alter its interior, which would require changing the geometry model.')+h('A fixed-surface example')+p('Take an internal height of 30 cm and a full water capacity of 800 g. Keep Water remaining at 50%: there are always 400 g of water, the surface stays at 15 cm, and the water’s own CG stays at 7.5 cm. Change only the bottle properties:')+table(['Empty-bottle mass','Mass ratio r','Empty-bottle CG height b','Height ratio β','Combined CG'],[
        ('100 g','0.125','15 cm','0.50','9.0 cm'),
        ('200 g','0.250','15 cm','0.50','10.0 cm'),
        ('100 g','0.125','7.5 cm','0.25','7.5 cm'),
        ('100 g','0.125','22.5 cm','0.75','10.5 cm')])+p('Every row has the same surface at 15 cm. The combined CG changes because the amount or location of bottle mass changes. In this cylindrical example, the calculation is the empty-bottle mass times its CG height plus 400 g times 7.5 cm, all divided by the total remaining mass.')+note('Try it: pause playback, set Water remaining to 50%, then move either ratio slider. The water surface stays fixed while the combined CG responds. '+('In this advanced explorer, Area slope also changes surface height at fixed volume fraction because it changes the interior shape. The table above uses Area slope = 0, a cylinder.' if advanced else 'Move Water remaining to change the surface. For this cylinder, depth is the fill fraction times the internal height.'))+'</section>'

math = '<h2>Watch the balance point move</h2>'+p('The water’s own center of gravity falls continuously. The bottle-and-water CG falls, then rises as low ballast disappears. The exact turning point is where the water surface meets the combined CG.')+simulator('ideal')
math+='<div class="reading">'+h('1. Specify the system before calculating')+p('The system is the bottle plus water remaining inside it. Swallowed water is excluded. Compare settled upright states between sips, with uniform gravity, incompressible water, a rigid cylindrical interior, negligible air mass, and no retained films. A cap is part of the empty-bottle mass only while attached. Center of mass and center of gravity coincide in a uniform gravitational field.'+cite(1))+symbols
math+=h('2. From a mass integral to a weighted average')+p('A slice at height s has mass ρA ds. Integrating mass and its first moment gives:'+cite(2))+eq(r'm(h)=\int_0^h\rho A\,ds=kh,\qquad J(h)=\int_0^h s\rho A\,ds=\frac{kh^2}{2}.')+p('Here J is the water’s first moment of mass about the bottom. Its centroid is J/m=h/2. Therefore')+eq(r'z(h)=\frac{Mb+J(h)}{M+m(h)}=\boxed{\frac{Mb+kh^2/2}{M+kh}}.')+p('This is a state calculation, not an energy-minimization principle. The normalization changes as water is removed.')
math+=h('3. Endpoints and the dip')+eq(r'z(0)=b,\qquad z(H)-b=\frac{kH}{M+kH}\left(\frac H2-b\right).')+p('The full and empty CGs agree only when b=H/2. Under that assumption:')+eq(r'z(H)=z(0)=H/2,\qquad z(h)-\frac H2=-\frac{k h(H-h)}{2(M+kh)}<0\quad(0<h<H).')+p('Every partially filled state is below the common endpoint. A heavy base or heavy neck changes the endpoints, not the weighted-average principle.')
math+=h('4. A differential identity with a physical meaning')+eq(r'\frac{dz}{dh}=\frac{k\left(Mh+kh^2/2-Mb\right)}{(M+kh)^2}=\boxed{\frac{k}{M+kh}[h-z(h)]}.')+p('During drinking, dh/dt is negative. Hence a water surface above the combined CG implies a falling CG; a surface below it implies a rising CG. The criterion uses the location of the layer missing between settled states, even when a straw withdraws water from the bottom.')+eq(r'\frac{dz}{dt}=\frac{k[h-z(h)]}{M+kh}\frac{dh}{dt}.')
math+=h('5. Solve the minimum and prove it is unique')+p('Let h* denote the critical water depth and z_min the minimum CG height. Set the derivative to zero:')+eq(r'\frac{k}{2}h_*^2+Mh_*-Mb=0,\qquad h_*=\frac{\sqrt{M^2+2kMb}-M}{k}=\frac{2Mb}{\sqrt{M^2+2kMb}+M}.')+p('The second expression avoids subtracting nearly equal numbers when the bottle is very heavy. At the minimum:')+eq(r'\boxed{z_{\min}=h_*}.')+p('For 0<b<H, the derivative’s numerator increases strictly from a negative value at the bottom to a positive value at the top. A stronger check is global convexity:')+eq(r'\frac{d^2z}{dh^2}=\frac{kM(M+2kb)}{(M+kh)^3}>0.')+p('Thus there is exactly one interior minimum. At b=0, the minimum is the empty endpoint; at M=0, the empty system has no defined CG and the usual return disappears.')
math+=h('6. Dimensionless form and asymptotics')+eq(r'y(f)=\frac{r\beta+f^2/2}{r+f},\qquad f_* = \sqrt{r^2+2r\beta}-r=\frac{2r\beta}{\sqrt{r^2+2r\beta}+r},\qquad y_{\min}=f_*.')+p('For a midpoint-balanced shell, β=1/2:')+eq(r'y(f)=\frac{r+f^2}{2(r+f)},\qquad f_*=\frac{1}{\sqrt{1+1/r}+1}.')+eq(r'r\to0^+:\ f_*\sim\sqrt r;\qquad r\to\infty:\ f_*=\frac12-\frac{1}{8r}+O(r^{-2}).')+p('A light bottle descends far before its shell regains control. A heavy bottle scarcely changes CG. The minimum is strictly below half-full for any finite positive r when β=1/2.')
math+=h('7. Time is a separate model')+p('Let q(t)≥0 be the water mass removed per unit time, and m_full the initial water mass. Then')+eq(r'm(t)=m_{\rm full}-\int_0^t q(s)\,ds,\qquad f(t)=\frac{m(t)}{m_{\rm full}},\qquad z(t)=H y(f(t)).')+p('For constant q and total duration T=m_full/q, f=1−τ. Pauses give plateaus, and changes in rate stretch the same state curve horizontally. They cannot create a new settled turning point while fill decreases monotonically.')+eq(r'\frac{z(t)}H=\frac{r\beta+(1-\tau)^2/2}{r+1-\tau},\qquad t_*/T=1-f_*.')
math+=h('8. The running numerical example')+p('Use H=30 cm, M=100 g, full water mass 800 g, and b=15 cm. Then r=1/8, f*=1/4, and z_min=7.5 cm. If emptied uniformly in 20 minutes, the minimum occurs at 15 minutes.')+table(['Water remaining','Depth','Combined CG'],[('100%','30 cm','15.00 cm'),('75%','22.5 cm','11.79 cm'),('50%','15 cm','9.00 cm'),('25%','7.5 cm','7.50 cm'),('10%','3 cm','9.00 cm'),('0%','0 cm','15.00 cm')])+note('The simulator is dimensionless: changing H rescales all heights; changing the mass ratio or the empty-bottle CG changes the curve itself.')+'</div>'

intuition='<div class="reading"><h2>Discover the result without algebra</h2>'+p('Three arguments answer three different questions: must a dip exist, why can the CG rise, and where can the minimum occur? None requires tracking fluid particles.')
intuition+=h('1. The endpoints force a dip')+p('A full symmetric cylinder balances at mid-height. An empty midpoint-balanced shell also balances there. With any partial fill, the water balances below mid-height. Their combined balance point lies between the water’s and the shell’s, so it is below mid-height.')+'<blockquote>Every intermediate state is lower than both endpoints. The journey must descend and return.</blockquote>'+p('This proves that a minimum exists. It does not, by itself, prove there is only one. The uniqueness proof needs the ordered-layer argument in the mathematics tab.')
intuition+=h('2. Vanishing ballast resolves the paradox')+p('Replace the water in your mind with a single equivalent weight at its own balance point. As you drink, that weight moves downward and becomes lighter. Initially its downward motion matters most; near empty, its disappearance matters most.')+'<blockquote>Remove low ballast from a bottle and its balance point rises—even if no material moves upward.</blockquote>'+p('A center of gravity is a location computed from the mass distribution. It is not a marked particle that must travel with some piece of matter.')
intuition+=h('3. Half-full cannot be the minimum')+p('At half-full, the water surface is at the bottle’s midpoint. The water’s balance point is below it, so the combined CG is below it too. The next sip removes an effective top layer above the combined CG and therefore lowers it further.')+note('For a uniform cylinder whose empty shell balances at mid-height, the minimum must occur with less than half the water remaining. The mass ratio determines how much less.')
intuition+=h('4. The marginal-layer test')+p('Imagine removing a thin wafer from the settled water distribution. Removing a wafer above the balance point lowers the balance point. Removing one below raises it. The wafer has no first-order effect exactly when its height equals the current balance point.')+p('The wafer describes the difference between two settled states. The actual water molecules may follow complicated paths through a straw; that history does not affect the final mass distribution under these assumptions.')
intuition+=h('5. A geometric lever picture')+p('The empty shell pulls the combined CG toward its fixed balance point. The water pulls it toward a lower balance point. The displacement below the empty-shell CG is the water’s share of total mass multiplied by the separation between those two balance points. One factor shrinks during drinking, while the other grows. Their competition creates the dip.')
intuition+=h('6. Two extreme bottles expose the mechanism')+table(['Thought experiment','Prediction'],[('Almost weightless shell','The combined CG tracks the water far downward, then rises sharply near empty.'),('Very heavy shell','The shell anchors the CG; the dip is shallow.'),('All shell mass at the bottom','No higher shell balance point remains to pull the CG up. The final rise disappears.'),('Last droplet pinned near the neck','The last water is high ballast. Removing it can lower the CG instead.')])
intuition+='<section id="symmetry">'+h('7. Can symmetry give the answer? Yes—but symmetry of what?')+p('Symmetry can locate the endpoints and, together with positivity of mass and continuity, establish a dip. It cannot by itself locate the minimum, prove uniqueness, or make the drinking trajectory symmetric in time. The key distinction is between symmetry of a mass distribution, symmetry of a first moment, and symmetry of a normalized center of gravity.')
intuition+=table(['Candidate symmetry','About what?','What it actually proves'],[('Axial rotations','The bottle’s vertical central axis','If the complete mass distribution is rotationally symmetric, the CG lies on that axis. This does not determine its height.'),('Top–bottom reflection','The horizontal plane at half the bottle’s height','A mass distribution unchanged by this reflection has its CG in that plane. This applies to a uniform full water column and to a reflection-symmetric empty shell.'),('Reflection of the remaining water alone','The horizontal plane halfway up the current water column','For a uniform cylindrical water column, its own CG is at half its current depth.'),('Complementary fills','Replace water-depth fraction f by 1−f, a reflection of the fill parameter about 1/2','Their first moments about the bottle midpoint are equal. Their CG heights are not equal because their total masses differ.'),('Reflection of the entire CG curve','A proposed vertical line at half-full or at the minimum','No exact reflection symmetry generally exists. Equal endpoints do not imply a symmetric curve.')])
intuition+=h('The short argument without mathematics')+p('Pair every mass element in the upper half of a full uniform water column with an equal element equally far below the midpoint. Their moments cancel. Do the same for a reflection-symmetric shell. The full bottle therefore balances at the midpoint; the empty shell does too.')+p('With a partial fill, the water column has its own reflection plane halfway up that shorter column, below the bottle midpoint. Its CG is therefore below the shell’s. The combined CG lies between them, so it is below the midpoint. As the fill changes continuously from full to empty, the CG must dip below the common endpoints and return.')+note('That is a symmetry-assisted proof of the existence of a minimum. The ingredients beyond symmetry are positive masses, the weighted-average property, and continuity. A midpoint CG of the shell is enough for the result; literal top–bottom shell symmetry is a sufficient condition, not a necessary one.')
intuition+=h('Why reflecting a half-empty bottle does not solve the problem')+p('Reflect a partially filled upright bottle across its midpoint plane. Water originally at the bottom now occupies the top, leaving air underneath. That is not another settled upright state under the same downward gravity. The allowed settled configurations are not closed under this reflection. Rotating the bottle upside down is also a different operation: the liquid redistributes, and the shell’s mass distribution need not be top–bottom symmetric.')+p('Even in the full and empty cases, the argument uses symmetry of the mass distribution. The complete gravitational experiment is not invariant under a horizontal reflection while the downward gravitational field is held fixed. Distribution symmetry is enough to locate the mass centroid in uniform gravity; a symmetry of the full dynamics is not required.')
intuition+=h('The subtler symmetry: equal moment, unequal CG')+p('For two complementary settled fills—for example one-quarter full and three-quarters full—the total mass moment about the bottle’s midpoint is the same. One way to see this: the bottom quarter has the opposite moment to its reflected top quarter. Since the complete water column has zero midpoint moment, the bottom three-quarters must have the same moment as the bottom quarter.')+p('But the quarter-full bottle has less total mass. The same negative moment divided by a smaller mass places its CG farther below the midpoint. Thus a quarter-full bottle balances lower than its three-quarter-full counterpart. The symmetric quantity is the unnormalized moment, not the CG.')+'<blockquote>The numerator has a complementary-fill symmetry. Dividing by a fill-dependent total mass breaks that symmetry in the CG.</blockquote>'
intuition+='<details id="symmetry-proof"><summary>Optional mathematical proof: reflection, complementary fills, and broken symmetry</summary>'
intuition+=p('Measure vertical position from the bottle midpoint: let ξ=s−H/2, where s is height above the bottom and H is bottle height. Let dm denote an element of mass. A distribution invariant under ξ→−ξ has an odd first-moment integrand, so')+eq(r'\int \xi\,dm=0,\qquad z_{CG}=H/2.')
intuition+=p('For the uniform cylindrical water column, retain k=ρA as water mass per unit height, h as current depth, M as shell mass, and b=H/2 as shell CG height. Define Q(h) as the combined first moment about the midpoint plane. The shell contributes zero; the water gives')+eq(r'Q(h)=\int_0^h(s-H/2)k\,ds=-\frac{k}{2}h(H-h),\qquad \boxed{Q(H-h)=Q(h)}.')
intuition+=p('Let f=h/H be the fill fraction, r=M/(kH)>0 the shell/full-water mass ratio, and y=z/H the normalized CG height. Dividing Q by the total mass gives')+eq(r'y(f)-\frac12=\frac{Q(fH)}{H(M+kHf)}=-\frac{f(1-f)}{2(r+f)}.')
intuition+=p('The product f(1−f) is unchanged under f→1−f. The denominator r+f is not. In fact,')+eq(r'\boxed{y(f)-y(1-f)=-\frac{f(1-f)(1-2f)}{2(r+f)(r+1-f)}}.')+p('For 0<f<1/2, this is strictly negative. Thus a global minimum cannot lie above half-full: its complementary state below half-full would have a lower CG. To exclude half-full itself without calculus, make a small downward change in f. The moment magnitude changes only quadratically, while total mass decreases linearly. The dip therefore initially deepens.')
intuition+=p('Precisely, let ε be a positive dimensionless amount smaller than 1/2, and define the normalized dip D(f)=1/2−y(f). Then')+eq(r'\frac{D(1/2-\varepsilon)}{D(1/2)}=\frac{(1-4\varepsilon^2)(r+1/2)}{r+1/2-\varepsilon}>1\quad\text{if}\quad0<\varepsilon<\min\!\left\{\frac12,\frac{1}{4(r+1/2)}\right\}.')+p('Consequently the minimum is strictly below half-full. This uses complementary-moment symmetry plus the normalization by mass; symmetry alone is insufficient. The unique location still follows from the turning-point or convexity argument in the full mathematics chapter:')+eq(r'f_*=\sqrt{r^2+r}-r,\qquad 0<f_*<1/2.')
intuition+=p('Nor is there a hidden exact reflection symmetry about f*. Such a symmetry would make every odd derivative vanish there. For this midpoint-shell cylinder, the third derivative with respect to f is')+eq(r'\frac{d^3y}{df^3}=-\frac{3r(r+1)}{(r+f)^4}\ne0\qquad(r>0).')+p('There is an approximate quadratic symmetry sufficiently close to the minimum, as for any smooth nondegenerate minimum, but no exact mirror symmetry of the full curve.')+'</details>'
intuition+=h('What survives if the shell is not midpoint-balanced?')+p('Let β=b/H denote the shell’s normalized CG height. Its midpoint moment is M H(β−1/2), which is constant as water is removed. Therefore the complementary-moment identity Q(H−h)=Q(h) still holds for a cylindrical interior, even though the full and empty CGs no longer coincide:')+eq(r'\frac{Q(fH)}{kH^2}=r(\beta-1/2)-\frac12 f(1-f).')+p('The sign of this common moment can now vary with fill and shell balance, so the lower-fill-versus-higher-fill ordering and the less-than-half-full minimum are no longer universal. A heavy-top shell can place the minimum above half-full. Shell reflection symmetry, midpoint balance, and cylindrical geometry must not be silently interchanged.')
intuition+=note('Answer to “symmetry about what?”: rotations about the vertical axis fix the lateral position; reflection about a horizontal midplane fixes the full/empty vertical centroids when the mass distributions permit it; reflection of the fill parameter f about 1/2 preserves the centered first moment. None is a symmetry of the complete normalized CG trajectory.')+'</section>'
intuition+=h('What these arguments do not justify')+p('They do not imply that gravity chooses a low-CG drinking trajectory, that ordinary drinking is upright, or that CG height alone predicts resistance to every disturbance. Those are separate questions.')+'</div>'

effects='<h2>Real-world effects: perturbations and new regimes</h2>'+p('Start with measurable geometry and shell balance, then add fluid dynamics only when the measurement demands it. A more elaborate model is useful when it changes a prediction you can test.')+simulator('real',True)+'<div class="reading">'
effects+=h('1. General cross-section: the exact rigid-container theorem')+p('Let A(s)>0 be horizontal interior area at height s, and retain uniform water density ρ, shell mass M, and fixed shell CG b. Define m(h) as water mass and J(h) as its first moment:')+eq(r'm(h)=\rho\int_0^h A(s)\,ds,\qquad J(h)=\rho\int_0^h sA(s)\,ds,\qquad z(h)=\frac{Mb+J(h)}{M+m(h)}.')+eq(r'\frac{dz}{dh}=\frac{\rho A(h)}{M+m(h)}[h-z(h)].')+p('To prove uniqueness, define N(h)=(M+m(h))(h−z(h)). Then')+eq(r'N(h)=M(h-b)+\rho\int_0^h(h-s)A(s)\,ds,\qquad N^{\prime}(h)=M+m(h)>0.')+p('For b strictly between the lowest and highest fluid-accessible elevations, N starts negative and ends positive. Hence the settled vertical CG has one interior minimum. The critical depth satisfies h*=z(h*). Geometry changes where it occurs, including the fraction of water remaining.')+note('Refinement of the earlier discussion: fixed tilt alone does not destroy this vertical-CG theorem. At a fixed orientation, describe the container by horizontal slices in the laboratory frame. Changing orientation during drinking, trapped compartments, capillarity, or motion can break the required one-parameter description.')
effects+=h('2. An analytic shape family you can explore')+p('Let u=h/H be dimensionless depth, a be an area-slope parameter with −1<a<1, and A₀ the mean cross-sectional area. Set A(Hu)=A₀[1+a(2u−1)]. Let V(u) be volume divided by full volume and Ĵ(u) the water moment divided by full-water mass times H.')+eq(r'V(u)=(1-a)u+a u^2,\qquad \widehat J(u)=\frac{1-a}{2}u^2+\frac{2a}{3}u^3.')+eq(r'\frac zH=\frac{r\beta+\widehat J(u)}{r+V(u)},\qquad f=V(u),\qquad u_* = \frac{r\beta+\widehat J(u_*)}{r+V(u_*)}.')+p('Positive a means a broader top; negative a means a broader base. The interface solves the last equation by bisection, using its unique root. The schematic is an axisymmetric container cross-section with width proportional to the square root of area.')
effects+=h('3. Air: an exact small correction')+p('Let ρw and ρa be constant water and air densities. Let V₀ be full internal volume, z_v its geometric centroid, and V(h), J_v(h) the occupied-water volume and its volume first moment. Replace an all-air interior with water in the occupied region:')+eq(r'M_e=M+\rho_a V_0,\qquad M_e b_e=Mb+\rho_a V_0z_v,\qquad \Delta\rho=\rho_w-\rho_a.')+eq(r'z(h)=\frac{M_e b_e+\Delta\rho\,J_v(h)}{M_e+\Delta\rho\,V(h)}.')+p('The same framework survives, with a modified baseline and density contrast. For room-condition estimates, ρa/ρw is of order 10⁻³. Actual values depend on temperature and pressure. This model assumes venting and approximately uniform air density; suction and a sealed flexible bottle need a different pressure–deformation model.')
effects+=h('4. Retained films, droplets, and moving shell material')+p('Let h be a state parameter, m_p(h) the pooled-water mass, J_p(h) its first moment, m_f(h) a retained-film mass, z_f(h) its centroid, and b(h) the shell CG for a shell of constant mass M. Primes below mean derivatives with respect to h. Define D and P as total mass and total first moment:')+eq(r'D=M+m_p+m_f,\quad P=Mb(h)+J_p+m_fz_f,\quad z=P/D.')+eq(r'z^{\prime}=\frac{Mb^{\prime}+m_p^{\prime}(h-z)+m_f^{\prime}(z_f-z)+m_fz_f^{\prime}}D,\qquad J_p^{\prime}=h m_p^{\prime}.')+p('The extra terms show exactly how the simple threshold can fail. Shell motion, film detachment, and changing film position can add turning points. If a discrete droplet of mass δm at height z_d is removed, let D be the mass before removal and z_before its CG:')+eq(r'z_{\rm after}-z_{\rm before}=\frac{\delta m\,(z_{\rm before}-z_d)}{D-\delta m}.')+p('Removing a neck droplet above the current CG produces a downward jump. A film may also make the state history-dependent: the same pooled depth can coexist with different retained-water distributions.')
effects+=h('5. Tilt: solve an occupied three-dimensional domain')+p('Let Ω be the interior in bottle-fixed coordinates r, Q a rotation into the laboratory frame, r₀ a translation, e_z the laboratory upward unit vector, and ℓ the laboratory water-surface elevation. The occupied region is Ωw(ℓ,Q).')+eq(r'\Omega_w(\ell,Q)=\{\mathbf r\in\Omega:\ \mathbf e_z\!\cdot(\mathbf r_0+Q\mathbf r)\leq\ell\}.')+p('Choose ℓ so its volume equals the prescribed water volume V. Let r_b be the shell CG in bottle coordinates. The laboratory CG is')+eq(r'\mathbf r_{CG}=\mathbf r_0+Q\,\frac{M\mathbf r_b+\rho\int_{\Omega_w}\mathbf r\,dV}{M+\rho V}.')+p('A changing Q adds orientation-dependent terms, so fill alone no longer determines the path. For a fixed Q, vertical slices recover the theorem above. A voxel integration or mesh-plane clipping algorithm can solve the static geometry; it is not a fluid-motion simulation.')
effects+=h('6. Capillarity: when the horizontal-surface approximation fails')+p('Define surface tension γ, gravitational acceleration g, representative liquid length L, and density contrast Δρ. The capillary length ℓ_c and Bond number Bo compare gravity with surface tension:'+cite(3))+eq(r'\ell_c=\sqrt{\frac\gamma{\Delta\rho g}},\qquad Bo=\frac{\Delta\rho g L^2}{\gamma}=\left(\frac L{\ell_c}\right)^2.')+p('For water near room temperature, γ≈0.072 N/m and Δρ≈1000 kg/m³ give ℓ_c≈2.7 mm. A centimeter-scale pool is gravity-dominated in its bulk, but thin films, small droplets, and corners can remain capillary-dominated. Use local liquid dimensions, not only the bottle radius.')+p('For a static interface, define p_l and p_g as liquid and gas pressures, and signed curvature κ so that a spherical liquid droplet has κ=2/R_d, where R_d is droplet radius. Then')+eq(r'p_l-p_g=\gamma\kappa,\qquad \nabla p_l=\rho\mathbf g.')+p('Together with contact-angle and contact-line conditions, these determine the interface. Advancing/receding contact-angle differences introduce hysteresis. Surface forces affect CG through the resulting mass distribution; they are not an extra mass in the CG formula.')
effects+=h('7. Sloshing: a dynamical extension, not a corrected static curve')+p('Let q be a displacement coordinate for a dominant slosh mode, ω its natural angular frequency, ζ its damping ratio, Γ a modal coupling factor, and a_x(t) the container’s horizontal acceleration. A reduced, small-amplitude model is:'+cite(4))+eq(r'\ddot q+2\zeta\omega\dot q+\omega^2q=-\Gamma a_x(t).')+p('Let r_w0 be the settled water centroid, e_x a horizontal unit vector, and c₂ a dimensionless geometry-dependent coefficient. For a symmetric tank and a dominant antisymmetric lateral mode, a schematic expansion is')+eq(r'\mathbf r_w=\mathbf r_{w0}+q\mathbf e_x+c_2\frac{q^2}{H}\mathbf e_z+\cdots,\qquad \mathbf r_{CG}=\frac{M\mathbf r_b+m\mathbf r_w}{M+m}.')+p('The horizontal centroid can move at first order while its vertical shift begins at second order by symmetry. This expansion is illustrative: ω, ζ, Γ, and c₂ require geometry-specific analysis or measurement and vary with fill. It is not a calibrated slosh prediction.')
effects+=h('8. The full fluid model and what closes it')+p('For a Newtonian incompressible liquid, define velocity field v, pressure p, dynamic viscosity μ, and body acceleration g. In an inertial frame:')+eq(r'\nabla\!\cdot\mathbf v=0,\qquad \rho\left(\partial_t\mathbf v+\mathbf v\!\cdot\nabla\mathbf v\right)=-\nabla p+\mu\nabla^2\mathbf v+\rho\mathbf g.')+p('A complete free-boundary problem also needs initial fluid shape and velocity, wall motion and no-slip conditions, free-surface kinematics, gas pressure and surface-stress conditions, outlet flux, and contact-line physics. The CG is then an integral over the evolving occupied liquid domain. For a deformable bottle, couple fluid traction to a structural constitutive law. These equations formulate the extension; this site does not claim to solve coupled CFD or fluid–structure interaction.')
effects+=h('9. Density gradients and a systematic perturbation expansion')+p('A fixed height-dependent density profile can be absorbed into a mass-per-height function λ(s)=ρ(s)A(s). Replace ρA by λ in the integrals and the same derivative and uniqueness theorem follow. If mixing or draining changes ρ throughout the occupied region, that fixed-profile assumption fails.')+p('Let ε be a small dimensionless perturbation, D₀ and P₀ baseline total mass and first moment, and δD and δP their linear perturbation coefficients. Write D=D₀+εδD, P=P₀+εδP, and z₀=P₀/D₀. Then')+eq(r'z=z_0+\varepsilon\frac{\delta P-z_0\delta D}{D_0}+\varepsilon^2\frac{z_0(\delta D)^2-\delta P\delta D}{D_0^2}+O(\varepsilon^3).')+p('This is a genuine first- and second-order expansion, rather than a list of loosely named second-order effects. A density perturbation δλ(s) at fixed depth contributes δD=∫δλ ds and δP=∫sδλ ds. Its first-order CG change is weighted by displacement from the original CG:')+eq(r'\delta z=\frac{1}{D_0}\int_0^h(s-z_0)\,\delta\lambda(s)\,ds.')+p('Added density above the CG raises it; added density below lowers it. A shape or density perturbation can be assessed without first rerunning a complete dynamic model.')
effects+=h('10. A gravity-gradient correction—and its limitation')+p('In an ideal parallel field whose downward magnitude is g(s)=g₀(1−αs), let g₀ be the bottom gravity magnitude and α a small inverse-length gradient with αH≪1. Let angle brackets denote averages over the complete mass distribution, including the shell. The height of the gravity-force-weighted centroid is')+eq(r'z_g=\frac{\langle s(1-\alpha s)\rangle}{\langle1-\alpha s\rangle}=z_{CM}-\alpha\left(\langle s^2\rangle-\langle s\rangle^2\right)+O(\alpha^2H^3).')+p('The bracketed quantity is vertical mass variance. A field weakening upward weights lower material more strongly. For a near-Earth estimate α≈2/R_E, where R_E≈6.37×10⁶ m is Earth’s radius. Since variance is at most H²/4 for a distribution confined to height H, a 30 cm bottle has a correction bounded at this order by about 7 nm. It is negligible compared with films or geometry errors. A fully nonparallel field generally cannot be represented by one universal CG point for all orientations; this formula is a parallel-field approximation, not a general definition.')
effects+=h('11. A rational modeling order')+table(['Order','What to measure or add','Expected benefit'],[('First','Shell mass and CG; interior volume versus height','Corrects endpoints and minimum with little complexity.'),('Second','Orientation, sipping schedule, retained water','Distinguishes geometry, timing, and history effects.'),('Third','Slosh frequency and damping; wall compliance','Explains transients and force measurements.'),('Only if needed','Free-surface CFD, capillary hysteresis, gas–shell coupling','Answers questions that static moments cannot.')])+'</div>'

family='<div class="reading wide"><h2>One mathematical structure, different physics</h2>'+p('The conservation laws differ. What matches is an additive numerator divided by an additive weight. Matching the full curve also requires matching the marginal-input profile.')
family+=table(['System','Weight W','Response Y','Additive numerator'],[('Bottle','Mass','Height','First moment of mass'),('Thermal mixing','Heat capacity','Temperature relative to a reference','Thermal-energy increment for constant heat capacities'),('Charge sharing','Capacitance','Voltage','Electric charge'),('Inelastic capture','Mass','Velocity component','Momentum component'),('Solution mixing','Mixture mass','Solute mass fraction','Solute mass')])
family+=h('1. Derive the universal balance law')+p('Let W₀>0 be the initial weight, Y₀ the initial response, x added weight, and U(x) the response carried by its next increment. Let P(x) be the accumulated numerator. The integration variable s measures added weight.')+eq(r'P(x)=W_0Y_0+\int_0^xU(s)\,ds,\quad W(x)=W_0+x,\quad Y(x)=\frac{P(x)}{W(x)}.')+eq(r'\boxed{\frac{dY}{dx}=\frac{U(x)-Y(x)}{W_0+x}}.')+p('Adding an increment pulls the average toward its value. The turning point is U=Y. Removing an identified increment reverses the sign. This is a balance identity, not necessarily a relaxation in time.')
family+=h('2. Exact bottle-shaped curves require a linear marginal input')+p('Choose reference added weight X>0 and response scale Y_ref>0. Measure responses relative to a fixed baseline so U(0)=0. Define f=x/X, r=W₀/X, y=Y/Y_ref, and y₀=Y₀/Y_ref. Set U(x)=Y_ref x/X.')+eq(r'y(f)=\frac{r y_0+f^2/2}{r+f},\quad \frac{dy}{df}=\frac{f-y}{r+f},\quad f_*=\sqrt{r^2+2r y_0}-r.')+p('Set y₀=1/2 and r=1/8 to recover the plotted example. The common minimum is f*=y_min=1/4. With a different marginal input the broad law survives, but the exact rational curve generally does not.')
family+='''<div class="plotbox"><h3>Dimensionless collapse</h3><div class="family-toggle"><label><input type="checkbox" data-family="0" checked> Thermal</label><label><input type="checkbox" data-family="1" checked> Electrical</label><label><input type="checkbox" data-family="2" checked> Momentum</label><label><input type="checkbox" data-family="3" checked> Solution</label><label>Mass / capacity ratio <input id="family-r" type="range" min="-2" max="1" step="any" value="-0.90308998699" aria-label="Shared weight ratio"><output id="family-r-value">0.125</output></label></div><svg id="family-plot" class="plot" viewBox="0 0 850 420" role="img" aria-label="Four independently evaluated normalized balance curves overlapping the bottle reference"></svg><p class="tiny">Solid cyan: bottle reference. Colored markers: four separately evaluated dimensional equations, normalized afterward. Dashed line: marginal input. Addition runs left → right; drinking runs right → left. This is amount, not elapsed time.</p><p class="status" id="family-error" aria-live="polite"></p></div>'''
family+=h('3. Thermal mixing')+p('Let C₀ be initial heat capacity, T₀ initial equilibrium temperature relative to a reference, x added heat capacity, and T_in(x) inlet temperature relative to that same reference. Constant heat capacities and an insulated, nonreacting system with negligible work give:'+cite(5))+eq(r'T(x)=\frac{C_0T_0+\int_0^xT_{in}(s)\,ds}{C_0+x}.')+p('Progressively warmer feed can still cool the contents while it remains colder than the current mixture. The minimum occurs when inlet and mixture temperatures coincide. Example: C₀=100 J/K, X=800 J/K, reference temperature 20°C, response scale 40 K, initial temperature 40°C, and inlet temperature 20°C+40 K·f. The mixture reaches 30°C at f=1/4.')+note('Correction to a loose earlier analogy: removing an aliquot from a well-mixed equilibrium liquid does not change its temperature. “Removing cold material warms the remainder” requires selectively removing a genuinely colder component before equilibration, not ordinary withdrawal from a uniform mixture.')
family+=h('4. Electrical charge sharing')+p('Let C₀ and V₀ be initial capacitance and voltage, x added capacitance, and V_in(x) the initial voltage of each independently precharged incoming increment. Keep the assembly isolated from batteries and allow transients to settle. Charge conservation gives:'+cite(6))+eq(r'V(x)=\frac{C_0V_0+\int_0^x V_{in}(s)\,ds}{C_0+x}.')+p('Example: C₀=1 μF, X=8 μF, initial voltage 6 V, and incoming voltage 12 V·f. The common voltage reaches 3 V at f=1/4. These are limiting infinitesimal additions; finite capacitor steps give a discrete approximation. Charge is conserved, while stored electrical energy can dissipate in the interconnections.')
family+=h('5. Inelastic capture and momentum')+p('Let M₀,v₀ denote initial cart mass and laboratory velocity; m accumulated captured mass; and U(m) incoming horizontal laboratory velocity. With negligible external horizontal impulse and complete capture:'+cite(7))+eq(r'v(m)=\frac{M_0v_0+\int_0^m U(s)\,ds}{M_0+m},\qquad (M_0+m)\frac{dv}{dm}=U-v.')+p('Example: M₀=2 kg, reference captured mass 16 kg, initial speed 3 m/s, and incoming speed 6 m/s·f. The minimum cart speed is 1.5 m/s at f=1/4. Momentum is the conserved numerator; kinetic energy is generally dissipated. An injector or interception geometry must actually deliver slower and faster material to the cart; a rear-only stream of slower material cannot catch it.')
family+=h('6. Nonreacting solution mixing')+p('Let M₀ be initial solution mass, c₀ its solute mass fraction, m added solution mass, and c_in(m) feed solute mass fraction. Retain all inflow, with no reaction, evaporation, precipitation, or outlet:')+eq(r'c(m)=\frac{M_0c_0+\int_0^m c_{in}(s)\,ds}{M_0+m}.')+p('Example: initial solution 0.25 kg at 5% solute by mass; reference added solution 2 kg; feed concentration 10%·f. The tank reaches 2.5% at f=1/4. Mass fractions avoid assuming that mixed volumes add. Inlet fractions must remain between zero and one.')
family+=h('7. Two ways the correspondence can fail')+p('First, a tank with an outlet has a different accumulated denominator. Second, sources, losses, reactions, or external forces add new numerator terms.')+p('Let S be a numerator source rate, W the current weight, and dots denote time derivatives. For a single inflow carrying U, without an outlet:')+eq(r'W\dot Y=\dot W(U-Y)+S.')+p('With fixed total weight, equal inflow/outflow rate q, perfectly mixed outflow, and inlet U, the balance becomes W·dY/dt=q(U−Y)+S. A fixed-weight tank can show exponential relaxation. Our growing-weight mixture generally does not. The familiar resemblance is not sufficient to claim identical time dynamics.')+'</div>'

unknown='<div class="reading"><h2>Unknown unknowns—and how to resolve them</h2>'+p('These are the conceptual traps most likely to survive even after the main derivation is understood. Each includes a way to check the claim.')
items=[
('The zero-mass shell is a singular limit',r'For any positive shell mass, the empty CG returns to b. If shell mass is exactly zero, the empty system has no CG. For the cylinder, taking fill to zero before shell mass gives β; reversing the limits gives zero. The limits do not commute.'+eq(r'\lim_{r\to0^+}\lim_{f\to0^+}y(f,r)=\beta,\qquad\lim_{f\to0^+}\lim_{r\to0^+}y(f,r)=0.')+'<p><strong>Check:</strong> move the mass-ratio slider toward its lower limit and examine the narrowing near-empty rise. A coarse plot can miss it.</p>'),
('A turning point has exceptional robustness',r'At the minimum, height of the last layer equals the current average. Small fill errors therefore affect CG only at second order. For a cylinder, let δf be a small fill perturbation and y_min the minimum response:'+eq(r'y(f_*+\delta f)=y_{\min}+\frac{(\delta f)^2}{2(r+f_*)}+O((\delta f)^3).')+'<p><strong>Check:</strong> sample fill symmetrically around the minimum. The first-order change cancels.</p>'),
('The optimum does not require a cylindrical bottle','The vertical-slice uniqueness theorem covers any fixed rigid orientation with a single bottom-filled water region. What changes is the map from height to volume. <strong>Check:</strong> vary the area slope and compare depth at the minimum with volume fraction at the minimum.'),
('The experiment’s frame can dominate the signal','A bottle raised to your mouth moves bodily upward even while its CG moves downward relative to its shell. In an accelerating frame the liquid responds to effective body acceleration; rotation can add spatially varying centrifugal terms. <strong>Check:</strong> keep the bottle fixed and drain it through a tube before trying a drinking experiment.'),
('The system boundary changes the answer','Bottle plus remaining water is an open system. Bottle plus water already swallowed plus the drinker is a different system, with a different CG. No paradox is resolved by applying closed-system momentum statements to only part of it. <strong>Check:</strong> write the included components before choosing a conservation law.'),
('Low CG does not mean hardest to knock over',r'For a rigid body with a frozen mass distribution, centered CG height z and circular support radius R_b, the quasistatic tipping angle is arctan(R_b/z). The energy barrier to pivot the CG over an edge is ΔE=Dg[√(z²+R_b²)−z], where D is total mass. Thus minimum height and maximum energy barrier need not coincide. Liquid redistribution changes this rigid-body calculation further.'+eq(r'\theta_c=\tan^{-1}(R_b/z),\qquad \Delta E=Dg\left(\sqrt{z^2+R_b^2}-z\right).')+'<p><strong>Check:</strong> distinguish the tilt threshold, energy barrier, sliding threshold, and impulse needed to topple. They answer different questions.</p>'),
('CG cannot identify the entire mass distribution','Different distributions can share the same mass and first moment but have very different moments of inertia and slosh responses. <strong>Check:</strong> compare two solid mock bottles with the same mass and CG but different radial ballast placement.'),
('A shared formula is weaker than shared physics','Thermal mixing dissipates temperature differences, capacitor sharing can dissipate electrical energy, and inelastic capture dissipates kinetic energy. The bottle moment calculation is geometric. Their normalized response equations agree under specific input protocols; their microscopic dynamics and entropy budgets do not. <strong>Check:</strong> list what is conserved and what is dissipated in each case.'),
('You can infer bottle properties from a CG experiment',r'Let u*=h*/H and r=M/m_full for a cylinder. The critical condition rearranges to'+eq(r'\beta=u_*+\frac{u_*^2}{2r},\qquad r=\frac{u_*^2}{2(\beta-u_*)}.')+'<p>If β is known, a measured turning depth estimates the mass ratio. If r is known, it estimates β. One turning point alone cannot independently identify both. <strong>Check:</strong> measure empty mass separately and compare the inferred β with a suspension measurement.</p>'),
('Differentiation amplifies noisy measurements','Finding the zero of a numerical derivative of measured CG can be unreliable. Fit the physical moment model to the raw data, estimate parameter uncertainty, then infer the minimum. Shared errors in height calibration or retained water are not cured by more repeated samples. <strong>Check:</strong> bootstrap repeated measurements and inspect residuals versus fill.'),
('Apparent balance can include forces other than weight','External buoyancy, a supporting straw, surface contact, or an attached hose can change measured forces and torques without changing the material center of mass. <strong>Check:</strong> isolate contact forces in a free-body diagram; do not fit every balance shift as a shifted mass centroid.'),
('“Very slow” has a timescale attached',r'Let T_d be the draining time and ω a characteristic slosh frequency. A large product ωT_d helps support a quasistatic approximation, but rapid individual sips or persistent low damping can still excite motion. Small capillary features can relax on other timescales. <strong>Check:</strong> wait for observed oscillations to decay after each change, rather than relying on the average drinking rate.')]
for title,body in items: unknown+='<details><summary>'+title+'</summary>'+p(body)+'</details>'
unknown+=note('A practical diagnostic: when data depart from the model, first ask whether the mass distribution changed, the system boundary changed, the reference frame changed, or the measurement includes an extra force. These explain more than adding an arbitrary correction coefficient.')+'</div>'

nextp='<div class="reading"><h2>Where to go next</h2>'+p('Turn a small mechanics puzzle into a sequence of falsifiable models. Each step should produce a measurement or artifact that can disagree with a prediction.')+'<ol class="timeline">'
projects=[
('Build a tabletop validation','Measure shell mass and full-water mass with a scale. Measure the empty CG using two suspension directions or calibrated support reactions. Drain in small increments with the bottle fixed and image the settled water geometry. For an independent balance check, reproduce selected settled distributions with rigid inserts matched in mass and centroid, then measure each rigid assembly by suspension or calibrated support torques. Simply tilting the liquid bottle does not measure its original upright CG: the water redistributes. Upright vertical support reactions locate the horizontal CG projection, not its height. Keep calculated liquid centroids and measured rigid-replica results clearly distinguished.','Output: data.csv, fitted parameters, residual plot, and uncertainty on the turning point.'),
('Design a geometry counterexample','Compare a broad-bottom and broad-top shape with the same height, full volume, shell mass, and shell CG. Predict the critical volume fraction numerically before measuring.','Output: a pair of CAD profiles and curves demonstrating why half-height is not half-volume.'),
('Run the thermal analogue','Use a well-insulated mixing vessel, a thermometer, and controlled additions whose inlet temperature rises with cumulative added heat capacity. Include the vessel’s thermal capacity. Stay within ordinary safe water temperatures.','Output: normalized temperature data overlaid with the bottle curve, with heat-loss residuals.'),
('Build a geometry solver before CFD','Represent the interior by a mesh or voxel grid. Clip it against a laboratory horizontal plane, solve surface elevation from volume, and integrate the occupied centroid at each orientation. Refine resolution to demonstrate convergence.','Output: an interactive tilted-bottle explorer with an error-versus-resolution report.'),
('Identify slosh from video','Hold fill fixed. Apply a small lateral displacement, release, and track the free-surface motion. Fit oscillation frequency and damping before coupling the mode to a CG calculation.','Output: a measured reduced-order model, with calibrated and uncalibrated parameters clearly separated.'),
('Study stability beyond CG','Compare the fill maximizing rigid-body tipping angle, the fill maximizing energy barrier, and the fill resisting a prescribed lateral impulse. Then allow liquid redistribution and measure the differences.','Output: a three-objective stability map; expect different optima.'),
('Make this an AI-agent science benchmark','Give a coding agent the verbal problem and require a model, symbol definitions, dimensional checks, uniqueness argument, counterexamples, plots, and numerical tests. Hold out heavy-base, noncylindrical, near-zero-mass, and pinned-droplet cases.','Output: a reproducible evaluation that scores scientific reasoning and assumptions, not just visual polish.')]
for title,body,result in projects:nextp+='<li><h3>'+title+'</h3>'+p(body)+p('<strong>'+result+'</strong>')+'</li>'
nextp+='</ol>'+h('A compact replication prompt')+'<blockquote>Model a changing weighted-average physical system. State its boundary and assumptions. Derive its conserved or additive numerator and its normalization. Prove the turning-point conditions, identify a singular limit, construct a counterexample outside the assumptions, and compare normalized data with the prediction. Separate geometric state equations from time dynamics.</blockquote>'

sources=[
('Uniform gravity and center of gravity','OpenStax, University Physics 1 §12.1','https://openstax.org/books/university-physics-volume-1/pages/12-1-conditions-for-static-equilibrium','Supports equivalence of center of gravity and center of mass in uniform gravity.'),
('Mass moments and continuous center of mass','OpenStax, University Physics 1 §9.6','https://openstax.org/books/university-physics-volume-1/pages/9-6-center-of-mass','Supports the mass-weighted integral definition. Bottle-specific proofs here are derived from it.'),
('Capillarity and surface tension','OpenStax, College Physics 2e §11.8','https://openstax.org/books/college-physics-2e/pages/11-8-cohesion-and-adhesion-in-liquids-surface-tension-and-capillary-action','Background for menisci, adhesion, and surface tension. The Bond-number scaling is derived in this page.'),
('Slosh modeling and experimental validation','NASA, Predicting Baffled Propellant Tank Slosh','https://nas.nasa.gov/SC15/demos/demo12.html','Supports the use of fluid models, slosh damping, and validation against experiment; our oscillator is a generic reduced model, not a NASA calibration.'),
('Calorimetry','OpenStax, University Physics 2 §1.4','https://openstax.org/books/university-physics-volume-2/pages/1-4-heat-transfer-specific-heat-and-calorimetry','Supports thermal energy balance and heat capacities.'),
('Capacitance and parallel connection','OpenStax, University Physics 2 §8.2','https://openstax.org/books/university-physics-volume-2/pages/8-2-capacitors-in-series-and-in-parallel','Supports Q=CV and addition of parallel capacitances. The sequential precharged-capacitor protocol is derived here.'),
('Perfectly inelastic collisions','OpenStax, College Physics 2e §8.5','https://openstax.org/books/college-physics-2e/pages/8-5-inelastic-collisions-in-one-dimension','Supports momentum conservation with kinetic-energy dissipation in complete capture.'),
('Free-surface fluid modeling','NASA NTRS, A CFD Approach to Modeling Spacecraft Fuel Slosh','https://ntrs.nasa.gov/archive/nasa/casi.ntrs.nasa.gov/20130012592.pdf','Background on evolving free surfaces and conservation-law CFD; this website implements static moment models, not CFD.')]
nextp+='<div class="sources"><h3>Sources and provenance</h3>'+p('Sources establish the standard physical laws. The bottle derivations, uniqueness proof, dimensionless mapping, worked examples, numerical models, and recommendations are calculations developed for this explainer. All figures shown in the app are computed diagrams or model predictions, not photographs or experimental data.')+'<ol>'+''.join(f'<li id="ref-{i}"><strong>{title}.</strong> <a href="{url}" target="_blank" rel="noopener noreferrer">{name}</a>. {scope}</li>' for i,(title,name,url,scope) in enumerate(sources,1))+'</ol></div></div>'

from visual_aids import enrich
math,intuition,effects,family,unknown,nextp=enrich(math,intuition,effects,family,unknown,nextp)
panels=[('math','Full mathematics',math),('intuition','Intuition',intuition),('effects','Real-world effects',effects),('family','Shared framework',family),('unknown','Unknown unknowns',unknown),('next','Next explorations',nextp)]
